package in.tallybridge.app;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.concurrent.*;

/** One customer screen combining Tally outstanding/activity with TallyBridge Orders. */
public final class Customer360Activity extends Activity {
 public static final String EXTRA_PARTY="party";
 private final ExecutorService work=Executors.newSingleThreadExecutor(); private final Handler main=new Handler(Looper.getMainLooper());
 private CryptoStore store; private BridgeApi api; private LinearLayout body; private ProgressBar progress; private String company,party; private boolean dark,destroyed;
 private int NAVY,TEAL,MUTED,BG,SURFACE,BORDER,TINT,AMBER,INK; private final NumberFormat money=NumberFormat.getCurrencyInstance(new Locale("en","IN"));
 @Override public void onCreate(Bundle b){applyTheme();super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);money.setCurrency(Currency.getInstance("INR"));try{store=new CryptoStore(this);api=new BridgeApi(store);company=store.get("company");}catch(Exception e){finish();return;}party=getIntent().getStringExtra(EXTRA_PARTY);if(party==null)party="";party=party.trim();if(party.isEmpty()){startActivity(new Intent(this,UniversalSearchActivity.class).putExtra(UniversalSearchActivity.EXTRA_MODE,UniversalSearchActivity.MODE_CUSTOMERS));finish();return;}frame();load();}
 @Override protected void onDestroy(){destroyed=true;work.shutdownNow();main.removeCallbacksAndMessages(null);super.onDestroy();}
 private String appearance(){return getSharedPreferences("appearance",MODE_PRIVATE).getString("mode","System");}
 private void applyTheme(){String m=appearance();dark=m.equals("Dark")||(m.equals("System")&&(getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES);setTheme(dark?R.style.AppThemeDark:R.style.AppThemeLight);NAVY=dark?0xffe6edf3:0xff102d44;TEAL=dark?0xff7bd8bd:0xff176b5b;MUTED=dark?0xffa7b8c5:0xff596c79;BG=dark?0xff101820:0xfff5f7fa;SURFACE=dark?0xff1b2732:Color.WHITE;BORDER=dark?0xff344552:0xffe4eaef;TINT=dark?0xff203f3a:0xffe5f2ee;AMBER=dark?0xffffc857:0xff8a5a00;INK=dark?0xff102d26:Color.WHITE;}
 private int dp(float x){return Math.round(x*getResources().getDisplayMetrics().density);} private LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;} private TextView txt(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setPadding(0,dp(3),0,dp(3));v.setLineSpacing(dp(2),1f);return v;}
 private GradientDrawable shape(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));d.setStroke(dp(1),BORDER);return d;} private LinearLayout.LayoutParams full(int t){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(t),0,0);return p;}
 private Button button(String s,View.OnClickListener l){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(TEAL);b.setTextSize(14);b.setBackground(shape(SURFACE,12));b.setMinHeight(dp(48));b.setOnClickListener(l);return b;} private Button primary(String s,View.OnClickListener l){Button b=button(s,l);b.setTextColor(INK);b.setBackground(shape(TEAL,12));return b;}
 private void frame(){LinearLayout root=col();root.setBackgroundColor(BG);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(dp(18),dp(15),dp(18),dp(9));LinearLayout titles=col();TextView brand=txt("CUSTOMER 360",10,TEAL);brand.setTypeface(null,Typeface.BOLD);brand.setLetterSpacing(.12f);titles.addView(brand);TextView h=txt(party,24,NAVY);h.setTypeface(null,Typeface.BOLD);titles.addView(h);titles.addView(txt(company,12,MUTED));top.addView(titles,new LinearLayout.LayoutParams(0,-2,1));top.addView(button("Back",v->finish()),new LinearLayout.LayoutParams(dp(82),dp(48)));root.addView(top);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(true);progress.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(TEAL));root.addView(progress,new LinearLayout.LayoutParams(-1,dp(3)));ScrollView sv=new ScrollView(this);body=col();body.setPadding(dp(18),dp(4),dp(18),dp(28));sv.addView(body);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
 private void load(){progress.setVisibility(View.VISIBLE);work.execute(()->{try{JSONObject x=api.get(BridgeApi.path("customer-workspace",company,"party",party,"refresh","1"));main.post(()->{if(destroyed)return;progress.setVisibility(View.GONE);paint(x);});}catch(Exception e){main.post(()->{if(destroyed)return;progress.setVisibility(View.GONE);body.removeAllViews();body.addView(txt("Customer details could not be loaded.\n"+(e.getMessage()==null?"Check TallyBridge connection.":e.getMessage()),15,MUTED),full(16));body.addView(button("Retry",v->load()),full(12));});}});}
 private void heading(String h,String d){TextView x=txt(h,19,NAVY);x.setTypeface(null,Typeface.BOLD);body.addView(x,full(18));if(d!=null&&!d.isEmpty())body.addView(txt(d,12,MUTED));}
 private View stat(String label,String value,String detail){LinearLayout c=col();c.setPadding(dp(14),dp(12),dp(14),dp(12));c.setBackground(shape(SURFACE,14));TextView l=txt(label,11,MUTED);l.setTypeface(null,Typeface.BOLD);c.addView(l);TextView v=txt(value,19,NAVY);v.setTypeface(null,Typeface.BOLD);c.addView(v);if(detail!=null&&!detail.isEmpty())c.addView(txt(detail,11,MUTED));return c;}
 private void paint(JSONObject x){body.removeAllViews();JSONObject c=x.optJSONObject("customer");if(c==null)c=new JSONObject();LinearLayout actions=new LinearLayout(this);Button share=primary("Share",v->ShareCenter.shareText(this,"Share customer",shareText(x)));Button order=button("+ Order",v->startActivity(new Intent(this,OrdersActivity.class).setAction(OrdersActivity.ACTION_NEW)));Button search=button("Search",v->startActivity(new Intent(this,UniversalSearchActivity.class)));actions.addView(share,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(7),0,0,0);actions.addView(order,p);LinearLayout.LayoutParams p2=new LinearLayout.LayoutParams(0,-2,1);p2.setMargins(dp(7),0,0,0);actions.addView(search,p2);body.addView(actions,full(8));
  LinearLayout r1=new LinearLayout(this);r1.addView(stat("OUTSTANDING",money.format(Math.abs(c.optDouble("outstanding"))),c.optInt("pendingBillCount")+" pending bill(s)"),new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams s2=new LinearLayout.LayoutParams(0,-2,1);s2.setMargins(dp(8),0,0,0);r1.addView(stat("OVERDUE",money.format(Math.abs(c.optDouble("overdue"))),"Saved bill-wise data"),s2);body.addView(r1,full(14));
  String purchase=x.optString("lastPurchaseDate");JSONObject lp=c.optJSONObject("lastPayment");String pay=lp==null?"No saved payment":money.format(Math.abs(lp.optDouble("amount")))+(lp.optString("date").isEmpty()?"":" • "+lp.optString("date"));heading("Relationship","Last purchase: "+(purchase.isEmpty()?"Not available":purchase)+"\nLast payment: "+pay);
  JSONArray freq=x.optJSONArray("frequentItems");if(freq!=null&&freq.length()>0){heading("Frequently bought","Based on saved invoice details");for(int i=0;i<freq.length();i++){JSONObject f=freq.optJSONObject(i);if(f!=null)body.addView(row(f.optString("name"),f.optInt("count")+" recent occurrence(s)",""),full(7));}}
  JSONArray pending=x.optJSONArray("pendingOrders");heading("Pending orders",pending==null||pending.length()==0?"No pending TallyBridge orders.":pending.length()+" pending order(s)");addOrders(pending,false);
  JSONArray dispatched=x.optJSONArray("dispatchedOrders");if(dispatched!=null&&dispatched.length()>0){heading("Recently dispatched",dispatched.length()+" recent order(s)");addOrders(dispatched,true);}
  JSONArray invoices=c.optJSONArray("latestInvoices");heading("Latest invoices",invoices==null||invoices.length()==0?"No saved invoices yet.":"");if(invoices!=null)for(int i=0;i<Math.min(invoices.length(),8);i++){JSONObject v=invoices.optJSONObject(i);if(v!=null)body.addView(row(v.optString("number","Invoice"),v.optString("date")+" • "+v.optString("voucherType"),money.format(Math.abs(v.optDouble("amount")))),full(7));}
 }
 private View row(String title,String detail,String value){LinearLayout c=col();c.setPadding(dp(14),dp(11),dp(14),dp(11));c.setBackground(shape(SURFACE,13));TextView t=txt(title,15,NAVY);t.setTypeface(null,Typeface.BOLD);c.addView(t);if(!detail.isEmpty())c.addView(txt(detail,12,MUTED));if(!value.isEmpty()){TextView v=txt(value,14,TEAL);v.setTypeface(null,Typeface.BOLD);c.addView(v);}return c;}
 private void addOrders(JSONArray a,boolean dispatched){if(a==null)return;for(int i=0;i<Math.min(a.length(),8);i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;StringBuilder items=new StringBuilder();JSONArray its=o.optJSONArray("items");if(its!=null)for(int j=0;j<its.length();j++){JSONObject it=its.optJSONObject(j);if(it==null)continue;if(items.length()>0)items.append(" • ");items.append(trim(it.optDouble("quantity"))).append(it.optString("unit").isEmpty()?"":" "+it.optString("unit")).append(" ").append(it.optString("name"));}body.addView(row(o.optString("number","Order"),items.toString(),dispatched?"DISPATCHED":"PENDING"),full(7));}}
 private String trim(double n){if(Math.rint(n)==n)return String.valueOf((long)n);return String.format(Locale.US,"%.2f",n).replaceAll("0+$","").replaceAll("\\.$","");}
 private String shareText(JSONObject x){JSONObject c=x.optJSONObject("customer");if(c==null)c=new JSONObject();String preset=c.optString("shareText").trim();StringBuilder b=new StringBuilder();b.append("Customer: ").append(party).append('\n');b.append("Outstanding: ").append(money.format(Math.abs(c.optDouble("outstanding")))).append('\n');b.append("Overdue: ").append(money.format(Math.abs(c.optDouble("overdue")))).append('\n');b.append("Pending bills: ").append(c.optInt("pendingBillCount"));if(!x.optString("lastPurchaseDate").isEmpty())b.append("\nLast purchase: ").append(x.optString("lastPurchaseDate"));if(!preset.isEmpty())b.append("\n\n").append(preset);return b.toString();}
}
